const incoming = $input.first().json;
let request = incoming.body ?? incoming;
if (Array.isArray(request) && request.length === 1) request = request[0];
if (!request || typeof request !== 'object' || Array.isArray(request)) {
  throw new Error('Webhook body must contain one website-enrichment request');
}
return [{ json: request }];

// n8n Code node: Run Once for All Items.
const request = $input.first().json;
const source = request.official_validation ?? request;
if (!source || typeof source !== 'object' || !Array.isArray(source.companies)) {
  throw new Error('Website enrichment requires a company collection');
}
if (typeof source.campaign_id !== 'string' || !source.campaign_id) throw new Error('Website enrichment requires campaign_id');
const limit = Math.max(1, Math.min(Number(request.maximum_enrichment_companies ?? source.companies.length), 200));
const companies = source.companies.slice(0, limit);
const unprocessedCompanies = source.companies.slice(limit);
if (!companies.length) throw new Error('Website enrichment received no companies');

return companies.map((company, index) => ({
  json: {
    campaign_id: source.campaign_id,
    company,
    website: company.website,
    enable_semantic_extraction: request.enable_semantic_extraction === true,
    source_company_count: source.companies.length,
    source_status: source.status,
    source_warnings: source.warnings ?? [],
    unprocessed_companies: index === 0 ? unprocessedCompanies : [],
  },
}));

// n8n Code node: Run Once for Each Item.
return {
  json: {
    campaign_id: $json.campaign_id,
    company: $json.company,
    company_id: $json.company.company_id,
    canonical_name: $json.company.canonical_name,
    website: $json.website,
  },
};

// n8n Code node: Run Once for Each Item.
const expected = $('Build Website Collector Request').item.json;
const result = $json;
const statuses = new Set(['COLLECTED', 'SKIPPED_NO_WEBSITE', 'BLOCKED_UNSAFE_URL', 'UNAVAILABLE']);
if (result.campaign_id !== expected.campaign_id || result.company_id !== expected.company_id) throw new Error('Website collector changed a controlled identifier');
if (!statuses.has(result.status) || !Array.isArray(result.pages) || !Array.isArray(result.warnings)) throw new Error('Invalid website collection envelope');
for (const page of result.pages) {
  for (const field of ['source_url', 'text', 'retrieved_at', 'checksum']) {
    if (typeof page[field] !== 'string' || !page[field]) throw new Error(`Website page requires ${field}`);
  }
}
return { json: result };

// n8n Code node: Run Once for Each Item.
const task = $('Prepare Website Enrichment Tasks').item.json;
return {
  json: {
    campaign_id: task.campaign_id,
    company: $json.company ?? task.company,
    collection: $json,
    enable_semantic_extraction: task.enable_semantic_extraction,
  },
};

// n8n Code node: Run Once for Each Item.
const expected = $('Build Fact Extraction Request').item.json;
const result = $json;
const statuses = new Set([
  'COMPLETED', 'COMPLETED_DETERMINISTIC', 'COMPLETED_FALLBACK',
  'SKIPPED_NO_WEBSITE', 'BLOCKED_UNSAFE_URL', 'UNAVAILABLE',
]);
if (result.campaign_id !== expected.campaign_id || result.company_id !== expected.company.company_id) throw new Error('Fact extraction changed a controlled identifier');
if (!statuses.has(result.status) || !Array.isArray(result.facts) || !Array.isArray(result.warnings)) throw new Error('Invalid fact-extraction envelope');
for (const fact of result.facts) {
  if (typeof fact.field !== 'string' || typeof fact.value_text !== 'string' || typeof fact.source_url !== 'string') throw new Error('Invalid extracted fact');
  if (fact.inferred !== false || typeof fact.extractor_confidence !== 'number' || !Number.isFinite(fact.extractor_confidence) || fact.extractor_confidence < 0 || fact.extractor_confidence > 1) throw new Error('Invalid fact provenance or confidence');
  if (!fact.value_text.trim() || typeof fact.evidence_text !== 'string' || !fact.evidence_text.trim() || typeof fact.retrieved_at !== 'string' || !Number.isFinite(Date.parse(fact.retrieved_at)) || typeof fact.uncertainty !== 'string' || !fact.uncertainty.trim()) throw new Error('Missing fact evidence or timestamp');
  const page = (expected.collection?.pages ?? []).find(page => page.source_url === fact.source_url && page.retrieved_at === fact.retrieved_at);
  const quoted = page && (String(page.text ?? '').includes(fact.evidence_text)
    || (page.evidence_links ?? []).some(link => link.value === fact.evidence_text));
  if (!quoted) throw new Error('Fact quote is absent from the retrieved source page');
  // n8n's restricted Code runtime does not expose the URL global. Accept only
  // absolute HTTP(S) DNS-host URLs without credentials or ambiguous separators.
  const source = fact.source_url.match(/^https?:\/\/([^/?#]+)(?:[/?#][^\s\\]*)?$/i);
  const authority = source?.[1].match(/^([a-z0-9](?:[a-z0-9.-]*[a-z0-9])?)(?::([0-9]{1,5}))?$/i);
  if (!authority || authority[1].split('.').some(label => !label || label.length > 63 || label.startsWith('-') || label.endsWith('-')) || (authority[2] && (Number(authority[2]) < 1 || Number(authority[2]) > 65535)) || /[\s\\\u0000-\u001f\u007f]/.test(fact.source_url)) throw new Error('Invalid fact source URL');
}
return { json: result };

// n8n Code node: Run Once for All Items.
const results = $input.all().map((item) => item.json);
const tasks = $('Prepare Website Enrichment Tasks').all().map((item) => item.json);
if (results.length !== tasks.length) throw new Error('Extraction result count does not match website task count');
const resultByCompany = new Map(results.map((result) => [result.company_id, result]));
const unique = (values) => [...new Set(values.filter(Boolean))];
const acceptedFacts = results.flatMap((result) => result.facts ?? []);
const baselineCompleteness = (company) => {
  const fields = [company.website, company.phones?.length, company.emails?.length, company.description, company.address, company.legal_identifier, company.social_profiles?.length];
  return Number((fields.filter(Boolean).length / fields.length).toFixed(2));
};

function factsFor(result, field) {
  return result.facts.filter((fact) => fact.field === field && Number(fact.extractor_confidence) >= 0.8).map((fact) => fact.value_text);
}

const fold = (value) => String(value ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
const governorates = ['Tunis','Ariana','Ben Arous','Manouba','Nabeul','Zaghouan','Bizerte','Béja','Jendouba','Le Kef','Siliana','Sousse','Monastir','Mahdia','Sfax','Kairouan','Kasserine','Sidi Bouzid','Gabès','Médenine','Tataouine','Gafsa','Tozeur','Kébili'];
function locationFromFacts(facts) {
  const addresses = unique(facts.filter((fact) => fact.field === 'address' && fact.inferred === false
    && fact.source_url && fact.retrieved_at && fact.evidence_text && Number(fact.extractor_confidence) >= 0.8)
    .map((fact) => fact.value_text));
  const observed = unique(governorates.filter((place) => addresses.some((address) => {
    const token = fold(place);
    const value = fold(address);
    return new RegExp(`(^|[^a-z])${token}($|[^a-z])`).test(value);
  })));
  return {address: addresses.length === 1 ? addresses[0] : null,
    governorate: observed.length === 1 ? observed[0] : null,
    evidence: facts.filter((fact) => fact.field === 'address' && addresses.includes(fact.value_text))
      .map((fact) => ({source_url:fact.source_url,value_text:fact.value_text}))};
}

const enrichedCompanies = tasks.map((task) => {
  const result = resultByCompany.get(task.company.company_id);
  task = {...task, company: result?.company ?? task.company};
  if (!result) throw new Error(`Missing extraction result for ${task.company.company_id}`);
  const legalIdentifier = task.company.legal_identifier
    ?? result.facts.find((fact) => fact.field === 'legal_identifier' && Number(fact.extractor_confidence) >= 0.95)?.value_text
    ?? null;
  const emails = unique([...(task.company.emails ?? []), ...factsFor(result, 'email')]);
  const phones = unique([...(task.company.phones ?? []), ...factsFor(result, 'phone')]);
  const socialProfiles = unique([
    ...(task.company.social_profiles ?? []),
    ...factsFor(result, 'linkedin'), ...factsFor(result, 'facebook'), ...factsFor(result, 'other_social'),
  ]);
  const description = result.summary || task.company.description || null;
  const location = locationFromFacts(result.facts);
  const address = location.address;
  const governorate = location.governorate;
  const completenessFields = [task.company.website, phones.length, emails.length, description, address, legalIdentifier, socialProfiles.length];
  return {
    ...task.company,
    address,
    governorate,
    location_evidence: location.evidence,
    legal_identifier: legalIdentifier,
    emails,
    phones,
    social_profiles: socialProfiles,
    description,
    enriched_facts: result.facts,
    public_signals: result.reputation_signals ?? [],
    website_enrichment: {
      status: result.status,
      extractor_version: result.extractor_version ?? null,
      collection_status: result.collection_status,
      document_checksum: result.document_checksum,
      model_used: result.model_used,
      flowise_flow_id: result.flowise_flow_id,
      warnings: result.warnings,
    },
    profile_completeness: Number((completenessFields.filter(Boolean).length / completenessFields.length).toFixed(2)),
    needs_rne_retry: !task.company.legal_identifier && Boolean(legalIdentifier),
  };
});
const unprocessedCompanies = tasks.flatMap((task) => task.unprocessed_companies ?? []).map((company) => ({
  ...company,
  website_enrichment: {
    status: 'NOT_ATTEMPTED_LIMIT',
    collection_status: 'NOT_ATTEMPTED',
    document_checksum: null,
    model_used: false,
    flowise_flow_id: null,
    warnings: ['Website enrichment batch limit reached'],
  },
  profile_completeness: company.profile_completeness ?? baselineCompleteness(company),
  needs_rne_retry: false,
}));
const companies = [...enrichedCompanies, ...unprocessedCompanies];

const unavailable = results.filter((result) => ['UNAVAILABLE', 'BLOCKED_UNSAFE_URL', 'SKIPPED_NO_WEBSITE'].includes(result.status)).length;
const fallback = results.filter((result) => result.status === 'COMPLETED_FALLBACK').length;
return [{
  json: {
    contract_version: '1.0',
    campaign_id: tasks[0].campaign_id,
    status: unavailable || fallback || unprocessedCompanies.length || companies.some(c => c.web_research?.status === 'PARTIAL') ? 'PARTIAL' : 'COMPLETED',
    company_count: companies.length,
    source_company_count: tasks[0].source_company_count,
    companies_enriched: results.filter((result) => result.status.startsWith('COMPLETED')).length,
    websites_collected: results.filter((result) => result.collection_status === 'COLLECTED').length,
    skipped_no_website: results.filter((result) => result.status === 'SKIPPED_NO_WEBSITE').length,
    unavailable_or_blocked: unavailable,
    not_attempted_limit: unprocessedCompanies.length,
    flowise_extractions: results.filter((result) => result.model_used).length,
    deterministic_extractions: results.filter((result) => !result.model_used && result.status.startsWith('COMPLETED')).length,
    fallback_count: fallback,
    facts_accepted: acceptedFacts.length,
    legal_identifiers_discovered: companies.filter((company) => company.needs_rne_retry).length,
    companies,
    warnings: [...new Set([...(tasks[0].source_warnings ?? []), ...results.flatMap((result) => result.warnings ?? [])])],
  },
}];

// n8n Code node: Run Once for Each Item.
const result = $json;
if (result.contract_version !== '1.0' || typeof result.campaign_id !== 'string') throw new Error('Invalid website-enrichment contract');
if (!['COMPLETED', 'PARTIAL'].includes(result.status) || !Array.isArray(result.companies) || !Array.isArray(result.warnings)) throw new Error('Invalid website-enrichment result');
if (result.company_count !== result.companies.length) throw new Error('Website-enrichment company count is inconsistent');
for (const company of result.companies) {
  if (!company.website_enrichment || typeof company.profile_completeness !== 'number') throw new Error('Company is missing website enrichment metadata');
}
return { json: result };
